  { code: "570", name: "Caja", balance: "AC_VII" },
  { code: "572", name: "Bancos e instituciones de crédito c/c", balance: "AC_VII" },
  { code: "602", name: "Compras de otros aprovisionamientos", pl: "4" },
  { code: "623", name: "Servicios de profesionales independientes", pl: "7" },
  { code: "628", name: "Suministros", pl: "7" },
  { code: "629", name: "Otros servicios", pl: "7" },
  { code: "630", name: "Impuesto sobre beneficios", pl: "17" },
  { code: "631", name: "Otros tributos", pl: "7" },
